"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface CountUpProps extends React.HTMLAttributes<HTMLElement> {
  /** target number to animate toward. */
  value: number;
  /** tween length in seconds. default 1. */
  duration?: number;
  /** fixed decimal places. default 0. ignored when `format` is set. */
  decimals?: number;
  /** custom formatter; overrides `decimals`. */
  format?: (n: number) => string;
  /** text rendered before the number. */
  prefix?: string;
  /** text rendered after the number. */
  suffix?: string;
  /** element/tag to render as. default "span". */
  as?: React.ElementType;
}

// easeOutCubic — fast start, gentle settle.
const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

/** Animated number that tweens from its previous value to `value` on change. */
export function CountUp({
  value,
  duration = 1,
  decimals = 0,
  format,
  prefix,
  suffix,
  as: Tag = "span",
  className,
  ...rest
}: CountUpProps) {
  const [display, setDisplay] = React.useState(value);
  // track the value currently shown so each tween starts where the last ended.
  const displayRef = React.useRef(value);
  const rafRef = React.useRef<number | null>(null);

  React.useEffect(() => {
    const from = displayRef.current;
    const to = value;
    if (from === to) return;

    if (duration <= 0 || prefersReducedMotion()) {
      displayRef.current = to;
      setDisplay(to);
      return;
    }

    const durationMs = duration * 1000;
    let start: number | null = null;

    const tick = (now: number) => {
      if (start === null) start = now;
      const elapsed = now - start;
      const t = Math.min(1, elapsed / durationMs);
      const current = from + (to - from) * easeOut(t);
      displayRef.current = current;
      setDisplay(current);
      if (t < 1) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        displayRef.current = to;
        setDisplay(to);
        rafRef.current = null;
      }
    };

    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    };
  }, [value, duration]);

  const text = format ? format(display) : display.toFixed(decimals);

  return (
    <Tag className={cn("tabular-nums", className)} {...rest}>
      {prefix}
      {text}
      {suffix}
    </Tag>
  );
}
